create extension if not exists postgis with schema public;
create extension if not exists pgcrypto with schema public;
create type public.member_role as enum ('admin','manager','engineer','inspector','viewer');
create table public.organisations(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 160),created_at timestamptz not null default now());
create table public.memberships(organisation_id uuid references public.organisations on delete cascade,user_id uuid references auth.users on delete cascade,role public.member_role not null,primary key(organisation_id,user_id));
create table public.projects(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations,name text not null check(length(name) between 2 and 160),description text not null default '',location text not null default '',start_m numeric not null check(start_m>=0),end_m numeric not null,created_at timestamptz not null default now(),unique(id,organisation_id),check(end_m>start_m));
create table public.project_memberships(project_id uuid not null,organisation_id uuid not null,user_id uuid not null,role public.member_role not null,primary key(project_id,user_id),foreign key(project_id,organisation_id) references public.projects(id,organisation_id),foreign key(organisation_id,user_id) references public.memberships);
create or replace function public.project_role(p uuid) returns public.member_role language sql stable security definer set search_path=public,pg_temp as $$ select case when m.role='admin' then 'admin'::member_role else pm.role end from projects pr join memberships m on m.organisation_id=pr.organisation_id and m.user_id=auth.uid() left join project_memberships pm on pm.project_id=pr.id and pm.user_id=auth.uid() where pr.id=p $$;
create or replace function public.org_admin(o uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from memberships where organisation_id=o and user_id=auth.uid() and role='admin') $$;
create table public.alignments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,name text not null,start_m numeric not null check(start_m>=0),end_m numeric not null,geometry jsonb not null,geom public.geometry(LineString,4326) not null,calibration jsonb not null default '[]',unique(id,project_id),check(end_m>start_m));
create index alignments_spatial on public.alignments using gist(geom);
create table public.issues(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,alignment_id uuid not null,reference text not null unique default ('CIQ-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),title text not null check(length(title) between 3 and 200),description text not null default '',category text not null check(category in ('Defect','Non-conformance','Safety','Environmental','Observation')),severity text not null check(severity in ('Critical','High','Medium','Low')),status text not null default 'Open' check(status in ('Open','Assigned','In Progress','Ready for Review','Closed')),start_m numeric not null,end_m numeric,offset_m numeric not null default 0,longitude double precision check(longitude between -180 and 180),latitude double precision check(latitude between -90 and 90),accuracy_m numeric check(accuracy_m>=0),location_source text not null default 'manual' check(location_source in ('manual','gps','surveyed')),assignee_id uuid references auth.users,due_date date,resolution text not null default '',version integer not null default 1,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,project_id),foreign key(alignment_id,project_id) references public.alignments(id,project_id),check(end_m is null or end_m>=start_m),check((longitude is null)=(latitude is null)));
create index issues_register on public.issues(project_id,status,severity,start_m);
create index issues_due on public.issues(project_id,due_date) where status<>'Closed';
create table public.inspection_templates(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,title text not null,questions jsonb not null check(jsonb_typeof(questions)='array'));
create table public.inspections(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,title text not null,due_date date,status text not null default 'Submitted' check(status in ('Submitted','Approved','Changes requested')),responses jsonb not null check(jsonb_typeof(responses)='array' and jsonb_array_length(responses)>0),issue_id uuid,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),unique(id,project_id),foreign key(issue_id,project_id) references public.issues(id,project_id));
create table public.corrective_actions(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,issue_id uuid not null,title text not null,status text not null default 'Open' check(status in ('Open','In Progress','Complete')),due_date date,assignee_id uuid references auth.users,created_at timestamptz not null default now(),foreign key(issue_id,project_id) references public.issues(id,project_id));
create table public.comments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,issue_id uuid not null,body text not null check(length(body) between 1 and 5000),created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),foreign key(issue_id,project_id) references public.issues(id,project_id));
create table public.evidence(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,issue_id uuid not null,filename text not null,storage_path text not null unique,mime_type text not null check(mime_type in ('image/jpeg','image/png','image/webp','application/pdf')),size_bytes bigint not null check(size_bytes between 1 and 10485760),scan_status text not null default 'quarantined' check(scan_status in ('quarantined','clean','rejected')),uploaded_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),foreign key(issue_id,project_id) references public.issues(id,project_id));
create table public.approvals(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,entity_id uuid not null,entity_type text not null,actor_id uuid not null default auth.uid() references auth.users,decision text not null,created_at timestamptz not null default now());
create table public.audit_events(id uuid primary key default gen_random_uuid(),project_id uuid references public.projects,organisation_id uuid not null references public.organisations,actor_id uuid references auth.users,action text not null,entity_type text not null,entity_id uuid not null,before_data jsonb,after_data jsonb,created_at timestamptz not null default clock_timestamp());
create index audit_project_time on public.audit_events(project_id,created_at desc);
create table public.notifications(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects,user_id uuid not null references auth.users,message text not null,created_at timestamptz not null default now(),read_at timestamptz);
create table public.invitations(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations,project_id uuid, email text not null,role public.member_role not null,token_hash text not null unique,expires_at timestamptz not null default now()+interval '7 days',accepted_at timestamptz,foreign key(project_id,organisation_id) references public.projects(id,organisation_id));
create table public.rate_limits(user_id uuid primary key references auth.users,window_start timestamptz not null,hits integer not null);
create function public.consume_rate_limit() returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare n int;begin if auth.uid() is null then return false;end if; insert into rate_limits values(auth.uid(),now(),1) on conflict(user_id) do update set hits=case when rate_limits.window_start<now()-interval '1 minute' then 1 else rate_limits.hits+1 end,window_start=case when rate_limits.window_start<now()-interval '1 minute' then now() else rate_limits.window_start end returning hits into n;return n<=60;end $$;
create function public.audit_change() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare payload jsonb; p uuid;o uuid;begin payload=case when TG_OP='DELETE' then to_jsonb(old) else to_jsonb(new) end;if TG_TABLE_NAME='projects' then p=(payload->>'id')::uuid;o=(payload->>'organisation_id')::uuid;elsif TG_TABLE_NAME in ('memberships','invitations') then p=(payload->>'project_id')::uuid;o=(payload->>'organisation_id')::uuid;else p=(payload->>'project_id')::uuid;select organisation_id into o from projects where id=p;end if;insert into audit_events(project_id,organisation_id,actor_id,action,entity_type,entity_id,before_data,after_data) values(p,o,auth.uid(),TG_OP,TG_TABLE_NAME,coalesce((payload->>'id')::uuid,(payload->>'user_id')::uuid),case when TG_OP<>'INSERT' then to_jsonb(old)-'token_hash' end,case when TG_OP<>'DELETE' then to_jsonb(new)-'token_hash' end);return coalesce(new,old);end $$;
create function public.check_alignment() returns trigger language plpgsql set search_path=public,pg_temp as $$ declare p projects;s jsonb;last_end numeric:=-1;begin select * into p from projects where id=new.project_id;if new.start_m<p.start_m or new.end_m>p.end_m then raise exception 'Alignment outside project boundaries';end if;if new.geometry->>'type'<>'LineString' then raise exception 'Import a GeoJSON LineString';end if;new.geom=ST_SetSRID(ST_GeomFromGeoJSON(new.geometry::text),4326);if ST_IsEmpty(new.geom) or not ST_IsValid(new.geom) or ST_NPoints(new.geom)<2 or ST_XMin(new.geom::box3d)<-180 or ST_XMax(new.geom::box3d)>180 or ST_YMin(new.geom::box3d)<-90 or ST_YMax(new.geom::box3d)>90 then raise exception 'Invalid alignment geometry';end if;if jsonb_typeof(new.calibration)<>'array' then raise exception 'Calibration must be an array';end if;for s in select * from jsonb_array_elements(new.calibration) loop if not(s ?& array['distance_start','distance_end','chainage_start','chainage_end']) or (s->>'distance_start')::numeric<last_end or (s->>'distance_end')::numeric<=(s->>'distance_start')::numeric or (s->>'chainage_start')::numeric<new.start_m or (s->>'chainage_end')::numeric>new.end_m or (s->>'chainage_end')::numeric<=(s->>'chainage_start')::numeric then raise exception 'Invalid or overlapping calibration';end if;last_end=(s->>'distance_end')::numeric;end loop;return new;end $$;
create trigger alignment_validation before insert or update on public.alignments for each row execute function public.check_alignment();
create function public.check_issue() returns trigger language plpgsql set search_path=public,pg_temp as $$ declare a alignments;begin select * into a from alignments where id=new.alignment_id and project_id=new.project_id;if a.id is null or new.start_m<a.start_m or new.start_m>a.end_m or new.end_m>a.end_m then raise exception 'Chainage outside alignment boundaries';end if;if new.assignee_id is not null and not exists(select 1 from project_memberships where project_id=new.project_id and user_id=new.assignee_id) then raise exception 'Assignee must belong to this project';end if;if TG_OP='INSERT' then new.created_by=auth.uid();new.created_at=now();new.version=1;new.status='Open';else new.created_by=old.created_by;new.created_at=old.created_at;new.reference=old.reference;new.project_id=old.project_id;new.version=old.version+1;end if;new.updated_at=now();return new;end $$;
create trigger issue_validation before insert or update on public.issues for each row execute function public.check_issue();
create function public.update_issue(p_id uuid,p_version int,p_status text,p_assignee uuid,p_resolution text,p_reason text default '') returns public.issues language plpgsql security definer set search_path=public,pg_temp as $$ declare i issues;r member_role;begin select * into i from issues where id=p_id for update;r=project_role(i.project_id);if r is null or r='viewer' then raise exception 'Forbidden' using errcode='42501';end if;if i.version<>p_version then raise exception 'Version conflict' using errcode='40001';end if;if p_status<>i.status then
 if i.status='Closed' then if p_status<>'Open' or r not in ('admin','manager','inspector') or length(trim(p_reason))<5 then raise exception 'Reopening requires reviewer permission and a reason';end if;
 elsif p_status='Closed' then if i.status<>'Ready for Review' or r not in ('admin','manager','inspector') or length(trim(p_resolution))<5 then raise exception 'Closure requires review permission and resolution evidence';end if;if exists(select 1 from corrective_actions where issue_id=i.id and status<>'Complete') then raise exception 'Complete corrective actions before closure';end if;if not exists(select 1 from evidence where issue_id=i.id and scan_status='clean') then raise exception 'Closure requires clean resolution evidence';end if;insert into approvals(project_id,entity_id,entity_type,decision) values(i.project_id,i.id,'issues','Closed');
 elsif not ((i.status='Open' and p_status in ('Assigned','In Progress')) or(i.status='Assigned' and p_status in ('In Progress','Open'))or(i.status='In Progress' and p_status in ('Ready for Review','Assigned'))or(i.status='Ready for Review' and p_status='In Progress')) then raise exception 'Invalid status transition';end if;
 end if;if p_status='Assigned' and p_assignee is null then raise exception 'Select an assignee';end if;if p_assignee is distinct from i.assignee_id and r not in ('admin','manager') then raise exception 'Only managers can assign work' using errcode='42501';end if;
 update issues set status=p_status,assignee_id=p_assignee,resolution=p_resolution where id=p_id returning * into i;if length(trim(p_reason))>0 then insert into comments(project_id,issue_id,body)values(i.project_id,i.id,p_reason);end if;return i;end $$;
create function public.bootstrap_organisation(p_name text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare o uuid;begin if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;if not consume_rate_limit() then raise exception 'Rate limit';end if;insert into organisations(name) values(p_name) returning id into o;insert into memberships values(o,auth.uid(),'admin');return o;end $$;
create function public.review_inspection(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare i inspections;begin select * into i from inspections where id=p_id for update;if coalesce(project_role(i.project_id)::text,'') not in ('admin','manager','inspector') then raise exception 'Forbidden' using errcode='42501';end if;if p_status not in ('Approved','Changes requested') then raise exception 'Invalid decision';end if;if i.created_by=auth.uid() then raise exception 'A second person must review this inspection';end if;update inspections set status=p_status where id=p_id;insert into approvals(project_id,entity_id,entity_type,decision)values(i.project_id,i.id,'inspections',p_status);end $$;
create function public.update_action(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare a corrective_actions;begin select * into a from corrective_actions where id=p_id for update;if coalesce(project_role(a.project_id)::text,'viewer')='viewer' then raise exception 'Forbidden' using errcode='42501';end if;if p_status not in ('Open','In Progress','Complete') then raise exception 'Invalid status';end if;update corrective_actions set status=p_status where id=p_id;end $$;
-- Privileged membership changes are audited and constrained to the same tenant by composite FKs.
create function public.create_invitation(p_org uuid,p_project uuid,p_email text,p_role member_role) returns text language plpgsql security definer set search_path=public,pg_temp as $$ declare token text;begin if not org_admin(p_org) then raise exception 'Forbidden' using errcode='42501';end if;if p_project is null and p_role<>'admin' then raise exception 'Select a project for non-admin members';end if;token=encode(gen_random_bytes(32),'hex');insert into invitations(organisation_id,project_id,email,role,token_hash)values(p_org,p_project,lower(trim(p_email)),p_role,encode(digest(token,'sha256'),'hex'));return token;end $$;
create function public.accept_invitation(p_token text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare i invitations;e text;begin select email into e from auth.users where id=auth.uid() and email_confirmed_at is not null;select * into i from invitations where token_hash=encode(digest(p_token,'sha256'),'hex') and accepted_at is null and expires_at>now() for update;if i.id is null or lower(e) is distinct from i.email then raise exception 'Invalid or expired invitation';end if;insert into memberships values(i.organisation_id,auth.uid(),i.role) on conflict do nothing;if i.project_id is not null then insert into project_memberships values(i.project_id,i.organisation_id,auth.uid(),i.role) on conflict do nothing;end if;update invitations set accepted_at=now() where id=i.id;end $$;
-- Default deny: explicitly grant only supported operations.
do $$ declare t text;begin foreach t in array array['organisations','memberships','projects','project_memberships','alignments','issues','inspection_templates','inspections','corrective_actions','comments','evidence','approvals','audit_events','notifications','invitations','rate_limits'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);end loop;end $$;
grant select on public.organisations,public.memberships,public.projects,public.project_memberships,public.alignments,public.issues,public.inspection_templates,public.inspections,public.corrective_actions,public.comments,public.evidence,public.approvals,public.audit_events,public.notifications to authenticated;
grant insert on public.projects,public.alignments,public.issues,public.inspection_templates,public.inspections,public.corrective_actions,public.comments,public.evidence to authenticated;
create policy organisations_read on public.organisations for select to authenticated using(exists(select 1 from memberships where organisation_id=id and user_id=auth.uid()));
create policy memberships_read on public.memberships for select to authenticated using(user_id=auth.uid() or org_admin(organisation_id));
create policy projects_read on public.projects for select to authenticated using(org_admin(organisation_id) or project_role(id) is not null);
create policy projects_create on public.projects for insert to authenticated with check(org_admin(organisation_id));
create policy project_members_read on public.project_memberships for select to authenticated using(project_role(project_id) is not null);
do $$ declare t text;begin foreach t in array array['alignments','issues','inspection_templates','inspections','corrective_actions','comments','evidence','approvals'] loop execute format('create policy project_read on public.%I for select to authenticated using(public.project_role(project_id) is not null)',t);end loop;foreach t in array array['issues','inspections','corrective_actions','comments'] loop execute format('create policy project_write on public.%I for insert to authenticated with check(public.project_role(project_id) in (''admin'',''manager'',''engineer'',''inspector''))',t);end loop;foreach t in array array['alignments','inspection_templates'] loop execute format('create policy manager_write on public.%I for insert to authenticated with check(public.project_role(project_id) in (''admin'',''manager''))',t);end loop;foreach t in array array['projects','alignments','issues','inspections','corrective_actions','comments','evidence','approvals','project_memberships','memberships','invitations','inspection_templates'] loop execute format('create trigger audit_change after insert or update or delete on public.%I for each row execute function public.audit_change()',t);end loop;end $$;
create policy evidence_write on public.evidence for insert to authenticated with check(project_role(project_id) in ('admin','manager','engineer','inspector') and uploaded_by=auth.uid() and scan_status='quarantined' and storage_path=project_id::text||'/'||issue_id::text||'/'||id::text);
create policy audit_read on public.audit_events for select to authenticated using(project_role(project_id) is not null or org_admin(organisation_id));
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid() and project_role(project_id) is not null);
-- Prevent spoofed identities, timestamps, or approval status through direct PostgREST inserts.
create function public.stamp_record() returns trigger language plpgsql as $$ begin new.created_at=now();if TG_TABLE_NAME in ('comments','inspections') then new.created_by=auth.uid();end if;if TG_TABLE_NAME='inspections' then new.status='Submitted';end if;if TG_TABLE_NAME='corrective_actions' then new.status='Open';end if;return new;end $$;
create trigger stamp_comment before insert on public.comments for each row execute function public.stamp_record();
create trigger stamp_inspection before insert on public.inspections for each row execute function public.stamp_record();
create trigger stamp_action before insert on public.corrective_actions for each row execute function public.stamp_record();
-- Private bucket: a trusted scanner updates evidence.scan_status using a separate privileged credential.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('evidence','evidence',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']);
create policy evidence_upload on storage.objects for insert to authenticated with check(bucket_id='evidence' and exists(select 1 from public.evidence e where e.storage_path=name and e.uploaded_by=auth.uid() and e.scan_status='quarantined' and public.project_role(e.project_id) in ('admin','manager','engineer','inspector')));
create policy evidence_download on storage.objects for select to authenticated using(bucket_id='evidence' and exists(select 1 from public.evidence e where e.storage_path=name and e.scan_status='clean' and public.project_role(e.project_id) is not null));
-- Remove implicit PUBLIC function execution. Trigger functions are not callable APIs.
do $$ declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('project_role','org_admin','consume_rate_limit','audit_change','check_alignment','check_issue','update_issue','bootstrap_organisation','review_inspection','update_action','create_invitation','accept_invitation','stamp_record') loop execute format('revoke execute on function %s from public,anon,authenticated',f.signature);end loop;end $$;
grant execute on function public.project_role(uuid),public.org_admin(uuid),public.consume_rate_limit(),public.bootstrap_organisation(text),public.update_issue(uuid,int,text,uuid,text,text),public.review_inspection(uuid,text),public.update_action(uuid,text),public.create_invitation(uuid,uuid,text,public.member_role),public.accept_invitation(text) to authenticated;
